SELECT c.comment_id, c.comment_post_id, c.comment_sent_user_id, su.user_nickname AS sent_user_nickname, c.comment_father_id, c.comment_receive_user_id, ru.user_nickname AS receive_user_nickname, c.comment_text, c.create_time FROM ch_post_comment c LEFT JOIN ch_user su ON su.user_id = c.comment_sent_user_id AND su.user_is_delete = 0 LEFT JOIN ch_user ru ON ru.user_id = c.comment_receive_user_id AND ru.user_is_delete = 0 WHERE c.comment_post_id = #{postId} AND c.comment_father_id = 0 AND c.comment_is_delete = 0
AND (c.create_time < #{cursorTime} OR (c.create_time = #{cursorTime} AND c.comment_id < #{cursorId}))
ORDER BY c.create_time DESC, c.comment_id DESC LIMIT #{pageSize}

SELECT c.comment_id, c.comment_post_id, c.comment_sent_user_id, su.user_nickname AS sent_user_nickname, c.comment_father_id, c.comment_receive_user_id, ru.user_nickname AS receive_user_nickname, c.comment_text, c.create_time FROM ch_post_comment c LEFT JOIN ch_user su ON su.user_id = c.comment_sent_user_id AND su.user_is_delete = 0 LEFT JOIN ch_user ru ON ru.user_id = c.comment_receive_user_id AND ru.user_is_delete = 0 WHERE c.comment_father_id IN
#{fatherId}
AND c.comment_is_delete = 0 ORDER BY c.comment_id ASC
